const message = $input.all()[0].json.message;

if (!message?.text) return [];

return message.text.trim()
  .split('\n')
  .map(line => line.trim())
  .filter(line => line.length > 0)
  .map(company => ({
    json: { company_name: company },
    pairedItem: { item: 0 } 
  }));

const data = $input.first().json; // Get current item data

// If company not found in LSEG
if (!data.found) {
  return [{
    json: {
      company: data.company || "Unknown",
      message: `Company "${data.company || "Unknown"}" not found in LSEG database or ESG data is not available.`,
      found: false
    }
  }];
}

// If found – prepare clean data and nice message
const company = data.company || $input.first().json.company_name;
const esg = data.esg_score;
const year = data.year;
const e = data.E && data.E !== "N/A" ? data.E : "-";
const s = data.S && data.S !== "N/A" ? data.S : "-";
const g = data.G && data.G !== "N/A" ? data.G : "-";
const pdf_url = data.pdf_url || null;

return [{
  json: {
    company: company,
    esg_score: esg,
    E: e,
    S: s,
    G: g,
    year: year,
    found: true,
    pdf_url: pdf_url,
    pdf_found: !!pdf_url,
    telegram_message: `
*${company}*

*LSEG ESG Score (Refinitiv)*
Overall Score: *${esg}/100*
Based on FY ${year} data

Environmental (E): *${e}/100*
Social (S): *${s}/100*
Governance (G): *${g}/100*

Data source: LSEG (Refinitiv) ESG Scores
Updated: November 2025

This message was sent automatically with n8n
    `.trim()
  }
}];

