const text = $input.first().json.data;

// استخراج همه لینک‌های PDF
const pdfRegex = /https?:\/\/[^\s\]]+\.pdf/gi;
const matches = text.match(pdfRegex) || [];

// فیلتر لینک‌های مرتبط
const filtered = matches.filter(url => 
  url.toLowerCase().includes('report') || 
  url.toLowerCase().includes('sustainab') || 
  url.toLowerCase().includes('esg') || 
  url.toLowerCase().includes('impact')
);

// اولین لینک معتبر رو برگردون
if (filtered.length > 0) {
  return [{ json: { pdf_url: filtered[0] } }];
} else {
  return [{ json: { pdf_url: "NotFound" } }];
}

// ===== بخش 1: خواندن داده‌ها =====
// داده‌های اصلی از Parse Result
const company = $('Parse Result').first().json.company;
const esg_score = $('Parse Result').first().json.esg_score;
const E = $('Parse Result').first().json.E;
const S = $('Parse Result').first().json.S;
const G = $('Parse Result').first().json.G;
const year = $('Parse Result').first().json.year;

// آدرس PDF از نود قبلی
const pdf_url = $('HTTP Request1').first().json.items[0].link || "Not available";

// ===== بخش 2: ساخت خط CSV =====
// ساخت خط CSV با 7 ستون (همانطور که گفتید)
const csvLine = `"${company.replace(/"/g, '""')}",${esg_score},${E},${S},${G},${year},"${pdf_url.replace(/"/g, '""')}"`;

// ===== بخش 3: دستور کامل برای ذخیره =====
const csvFile = '/home/node/.n8n/data/esg_dataset.csv';

// دستور bash برای:
// 1. ایجاد پوشه
// 2. ایجاد فایل با هدر اگر وجود ندارد
// 3. چک تکراری با grep
// 4. اضافه کردن خط جدید اگر تکراری نیست
const bashCommand = `
#!/bin/bash
CSV_FILE="${csvFile}"

# 1. ایجاد پوشه اگر وجود ندارد
mkdir -p /home/node/.n8n/data

# 2. اگر فایل وجود ندارد، هدرها را بنویس
if [ ! -f "$CSV_FILE" ]; then
    echo "Company,ESG_Score,E_Score,S_Score,G_Score,Year,PDF_URL" > "$CSV_FILE"
    echo "File created with headers"
fi

# 3. فرار کردن کوتیشن‌ها برای grep
COMPANY_ESCAPED=$(echo "${company}" | sed 's/"/""/g' | sed 's/\[/\\[/g' | sed 's/\]/\\]/g')

# 4. چک تکراری - آیا شرکت قبلاً وجود دارد؟
if grep -q "^\"$COMPANY_ESCAPED\"," "$CSV_FILE" 2>/dev/null; then
    echo "DUPLICATE"
    echo "Company '${company}' already exists in CSV"
    exit 0
else
    # 5. اضافه کردن خط جدید
    echo "${csvLine}" >> "$CSV_FILE"
    echo "ADDED"
    echo "Successfully added: ${company}"
    exit 0
fi
`;

// ===== بخش 4: خروجی =====
return [{
    json: {
        // 7 فیلد اصلی برای CSV
        company: company,
        esg_score: esg_score,
        E: E,
        S: S,
        G: G,
        year: year,
        pdf_url: pdf_url,

        // اطلاعات اضافی برای workflow
        csv_line: csvLine,
        csv_file: csvFile,
        bash_command: bashCommand,
        operation: "ready_to_append",

        // زمان برای ردیابی
        timestamp: new Date().toISOString()
    }
}];

const inputData = $input.first().json;
const company = inputData.company;

// 1. Escape کردن company برای bash در JavaScript
const escapedCompany = company
    .replace(/\\/g, '\\\\')     // \ -> \\
    .replace(/"/g, '\\"')       // " -> \"
    .replace(/\$/g, '\\$')      // $ -> \$
    .replace(/`/g, '\\`');      // ` -> \`

// 2. دستور ساده و مطمئن
const checkCommand = `
FILE="/data/esg_dataset.csv"
if [ ! -f "\$FILE" ]; then
  echo "CSV_NOT_FOUND"
elif grep -i "^\\"${escapedCompany}\\"," "\$FILE" > /dev/null 2>&1; then
  echo "DUPLICATE"
else
  echo "NEW"
fi
`;

// 3. یا حتی ساده‌تر - بدون quote پیچیده
const simpleCheckCommand = `
FILE="/data/esg_dataset.csv"
[ ! -f "\$FILE" ] && echo "CSV_NOT_FOUND" && exit 0
grep -i "${company}" "\$FILE" > /dev/null && echo "DUPLICATE" || echo "NEW"
`;

return [{
    json: {
        ...inputData,
        check_command: simpleCheckCommand.trim(),
        escaped_company: escapedCompany,
        original_company: company
    }
}];
